#include <bits/stdc++.h>
using namespace std;

const int MAXN=60;
const int MOD=1000000007;
long long n;
int k;

inline int add(int x){ return x>=MOD?x-MOD:x; }
inline int sub(int x){ return x<0?x+MOD:x; }
inline int mul(int x,int y){ return (long long)x*y%MOD; }

struct Mat {
    int mat[MAXN][MAXN];
    int size;
    void init() { memset(mat,0,sizeof(mat)); }
    void set_identity() {
        init();
        for(int i=1;i<=size;i++) mat[i][i]=1;
    }
    Mat operator *(const Mat& rhs) const {
        Mat res; res.size = size;
        long long tmp[MAXN][MAXN]; memset(tmp,0,sizeof(tmp));
        const long long MODLL=(LL)MOD*MOD;
        for(int i=1;i<=size;i++)
            for(int j=1;j<=size;j++)
                for(int k=1;k<=size;k++) {
                    tmp[i][j]+=(LL)mat[i][k]*rhs.mat[k][j];
                    if(tmp[i][j]>=MODLL) tmp[i][j]-=MODLL;
                }
        for(int i=1;i<=size;i++)
            for(int j=1;j<=size;j++)
                res.mat[i][j]=tmp[i][j]%MOD;
        return res;
    }
};

vector<vector<Mat>> f, sump, sums;
vector<int> num;
int cnt;

void main_process() {
    num.clear();
    for (long long x=n; x>0; x/=k)
        num.push_back(x%k);
    cnt=(int)num.size();

    f.resize(cnt, vector<Mat>(k));
    sump.resize(cnt, vector<Mat>(k));
    sums.resize(cnt, vector<Mat>(k));

    for (int i=0; i<cnt; i++) {
        for (int j=0; j<k; j++) {
            f[i][j].size=k+1; f[i][j].init(); f[i][j].set_identity();
            for(int t=1; t<=k+1; t++)
                f[i][j].mat[t][t]=1;
            for(int t=1; t<=k+1; t++)
                f[i][j].mat[i+1][t]=1; // index fix
        }
    }
    for (int j=0; j<k; j++) {
        sump[0][j]=f[0][j];
    }
    for (int i=1; i<cnt; i++) {
        for (int j=0; j<k; j++) {
            int idx = (j==0) ? 0 : (j);
            f[i][j] = (j==0) ? sums[i-1][j] : sump[i-1][j-1]*sums[i-1][j];
        }
        for (int j=0; j<k; j++) {
            if(j==0) sump[i][j]=f[i][j];
            else sump[i][j]=f[i][j]*sump[i][j-1];
        }
        for(int j=k-2;j>=0;j--) {
            sums[i][j]=sums[i][j+1]*f[i][j];
        }
    }
    Mat ans; ans.size=k+1; ans.set_identity();
    int sumIdx=0;
    for (int i=cnt-1; i>=0; i--) {
        for (int j=0;j<num[i];j++) {
            int idx = (sumIdx + j)%k;
            ans=f[i][idx]*ans;
        }
        sumIdx+=num[i]; sumIdx%=k;
    }
    int res=0;
    for (int i=1; i<=k+1; i++) {
        res=add(res+ans.mat[i][k+1]);
    }
    cout<<res<<endl;
}

int main() {
    cin>>n>>k;
    main_process();
}
